import{_ as a,o as n,c as t,a2 as e}from"./chunks/framework.D66Xq0Kv.js";const b=JSON.parse('{"title":"05 · 风格路线 — IP-Adapter（零训练风格跟随）","description":"","frontmatter":{},"headers":[],"relativePath":"05-风格路线-IPAdapter.md","filePath":"05-风格路线-IPAdapter.md"}'),i={name:"05-风格路线-IPAdapter.md"};function p(l,s,d,r,o,h){return n(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="_05-·-风格路线-—-ip-adapter-零训练风格跟随" tabindex="-1">05 · 风格路线 — IP-Adapter（零训练风格跟随）</h1><blockquote><p>场景：想让 AI 按&quot;某位老师的风格&quot;重绘你的画，不想训练。个人学习、不公开传播。</p></blockquote><h2 id="_1-心智模型" tabindex="-1">1. 心智模型</h2><ul><li><strong>IP-Adapter 是什么</strong>：一个作者已训练好的&quot;风格翻译官&quot;适配器——把参考图压缩成特征向量，注入生成过程的每一步，把输出&quot;拉向&quot;参考图的风格。<strong>零训练，推理时即时生效</strong>（查字典，不是背字典）</li><li><strong>复制深度</strong>：浅拷贝——配色、笔触质感、渲染风格等<strong>表层统计</strong>；抓不住构造逻辑（那是 01 §5 的边界）</li><li><strong>单图漂移，多图才稳</strong>：一张参考图的信息不够，给 <strong>3~5 张</strong>老师作品才锁得住</li><li><strong>与 ControlNet 正交</strong>：ControlNet 管骨架（长什么样），IP-Adapter 管风格（什么质感）——<strong>两者可叠加</strong>：&quot;老师风格的贴线重绘&quot; = ControlNet（你的线）+ IP-Adapter（老师的风格）</li><li><strong>与 LoRA 的取舍</strong>（详见 06）：</li></ul><table tabindex="0"><thead><tr><th></th><th>IP-Adapter</th><th>LoRA</th></tr></thead><tbody><tr><td>训练</td><td>无</td><td>需要（20~60 张 + 1~2 小时租卡）</td></tr><tr><td>生效</td><td>即时，每次传参考图</td><td>加载即用，长期复用</td></tr><tr><td>稳定性</td><td>多参考才稳</td><td>稳定</td></tr><tr><td>换老师</td><td>换图即可</td><td>重训</td></tr><tr><td>深度</td><td>浅</td><td>深</td></tr><tr><td>用途</td><td>验证方向、临时对比</td><td>确定长期学某位老师</td></tr></tbody></table><h2 id="_2-安装" tabindex="-1">2. 安装</h2><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 节点（cd 到 ComfyUI\\custom_nodes\\）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">git clone https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ghproxy.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">github.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cubiq</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ComfyUI_IPAdapter_plus.git</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>权重文件（路径和文件名按 cubiq README 要求，已实测核对 h94/IP-Adapter 仓库结构）：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ComfyUI\\models\\ipadapter\\ip-adapter-plus_sdxl_vit-h.safetensors</span></span>
<span class="line"><span>    ← https://hf-mirror.com/h94/IP-Adapter/resolve/main/sdxl_models/ip-adapter-plus_sdxl_vit-h.safetensors</span></span>
<span class="line"><span>      （风格跟随推荐 plus_vit-h 版）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ComfyUI\\models\\clip_vision\\CLIP-ViT-H-14-laion2B-s32B-b79K.safetensors</span></span>
<span class="line"><span>    ← https://hf-mirror.com/h94/IP-Adapter/resolve/main/models/image_encoder/model.safetensors</span></span>
<span class="line"><span>      （下载后改名为上面的名字，Unified Loader 要求精确文件名）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>备选：<code>ip-adapter_sdxl_vit-h.safetensors</code>（<code>sdxl_models/</code> 下，原版 vit-h）也可试，效果对比后定。 FaceID 系列需要额外 LoRA + insightface，<strong>本场景不需要</strong>。</p><h2 id="_3-工作流" tabindex="-1">3. 工作流</h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Load Checkpoint] NoobAI v1.1</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>[IPAdapter Unified Loader]  ← ipadapter=plus_sdxl_vit-h, clip_vision=ViT-H</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>[IPAdapter Advanced]  ← model=UNet, weight=0.6~0.9</span></span>
<span class="line"><span>        │                参考图 = 3~5 张老师作品（用 batch 合并节点接入，节点名以右键菜单为准）</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>[KSampler]（Euler a / 28 步 / CFG 5 / 固定种子）→ [VAE Decode] → [Save Image]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>与 W1 组合成&quot;老师风格贴线重绘&quot;：在 W1 的节点链上，把 IPAdapter Advanced 的输出并联进 KSampler 的 model 输入（ControlNet 管线稿 + IP-Adapter 管风格）。</p><p><strong>参数语义</strong>：</p><ul><li><code>weight</code>：风格强度。0.6~0.9 起步；太高 → 糊、内容丢失；太低 → 没风格</li><li><code>start/end</code>（时间步区间）：默认全区间；若&quot;风格压过结构&quot;，把 end 调低（如 0.8）让后半程回归内容</li></ul><h2 id="_4-验证与调参" tabindex="-1">4. 验证与调参</h2><ol><li>同一张画：无 IP-Adapter / weight 0.5 / 0.7 / 0.9 各出一张，固定种子</li><li>参考图数量：1 张 vs 3 张 vs 5 张对比（预期：1 张漂移明显）</li><li>与 W1-B（平均画师版）归档对比——差异 = 风格距离</li></ol><h2 id="_5-伦理" tabindex="-1">5. 伦理</h2><p>个人学习、不公开传播；别公开发布带老师风格化的输出；商用一律不行（模型本身禁止商用，仿冒在世画师风格商用是侵权风险）。</p><h2 id="_6-未验证项" tabindex="-1">6. 未验证项</h2><ul><li>plus_vit-h 与 NoobAI 的具体融合效果需实测（SDXL 通用适配器，无 NoobAI 专属调优）</li><li>batch 合并节点的确切名称以安装后右键菜单为准</li><li>参考图用老师原图 vs 用老师作品的线稿版，效果差异需自测</li></ul>`,21)])])}const u=a(i,[["render",p]]);export{b as __pageData,u as default};
